{
    struct lexer lx;
    qs_clear_error();
    if (qs_lex(text, &lx)) {
        qs_lex_free(&lx);
        return -1;
    }
#ifdef QS_DEBUG
    fprintf(stderr, "qs_eval: %d tokens in \"%s\"\n", lx.count, text);
#endif
    int rc = qs_parse(&lx, out);
    qs_lex_free(&lx);
    return rc;
}

